solution.solution.cpp:
#include <string>
#include <vector>

struct Scene { std::string name; bool coversBelow; };

class SceneStack
{
public:
    void push(Scene s) { m_requests.push_back({ Kind::Push, std::move(s) }); }
    void pop() { m_requests.push_back({ Kind::Pop, {} }); }
    void replace(Scene s) { m_requests.push_back({ Kind::Replace, std::move(s) }); }
    void clear() { m_requests.push_back({ Kind::Clear, {} }); }

    void apply()
    {
        for (Request& r : m_requests)
        {
            switch (r.kind)
            {
            case Kind::Push: m_stack.push_back(std::move(r.scene)); break;
            case Kind::Pop: if (!m_stack.empty()) m_stack.pop_back(); break;
            case Kind::Replace: if (!m_stack.empty()) m_stack.pop_back(); m_stack.push_back(std::move(r.scene)); break;
            case Kind::Clear: m_stack.clear(); break;
            }
        }
        m_requests.clear();
    }

    std::string top() const { return m_stack.empty() ? "" : m_stack.back().name; }

    std::vector<std::string> drawOrder() const
    {
        std::vector<std::string> out;
        if (m_stack.empty()) return out;
        std::size_t first{ m_stack.size() - 1 };
        while (first > 0 && !m_stack[first].coversBelow) --first;
        for (std::size_t i{ first }; i < m_stack.size(); ++i) out.push_back(m_stack[i].name);
        return out;
    }

    std::size_t size() const { return m_stack.size(); }

private:
    enum class Kind { Push, Pop, Replace, Clear };
    struct Request { Kind kind; Scene scene; };
    std::vector<Scene> m_stack;
    std::vector<Request> m_requests;
};

unitTests:
using Names = std::vector<std::string>;
TEST("requests wait for apply") { SceneStack s; s.push({ "title", true }); CHECK_EQ(s.size(), std::size_t{ 0 }); s.apply(); CHECK_EQ(s.top(), std::string("title")); }
TEST("replace and pause") {
    SceneStack s; s.push({ "title", true }); s.apply();
    s.replace({ "game", true }); s.apply(); CHECK_EQ(s.size(), std::size_t{ 1 }); CHECK_EQ(s.top(), std::string("game"));
    s.push({ "pause", false }); s.apply(); CHECK_EQ(s.drawOrder(), (Names{ "game", "pause" }));
    s.push({ "options", false }); s.apply(); CHECK_EQ(s.drawOrder(), (Names{ "game", "pause", "options" }));
    s.pop(); s.pop(); s.apply(); CHECK_EQ(s.top(), std::string("game"));
}
TEST("covering scenes hide what is below") { SceneStack s; s.push({ "game", true }); s.push({ "shop", true }); s.push({ "tooltip", false }); s.apply(); CHECK_EQ(s.drawOrder(), (Names{ "shop", "tooltip" })); }
TEST("nothing covers") { SceneStack s; s.push({ "a", false }); s.push({ "b", false }); s.apply(); CHECK_EQ(s.drawOrder(), (Names{ "a", "b" })); }
TEST("order of requests") {
    SceneStack s; s.push({ "game", true }); s.push({ "pause", false }); s.apply();
    s.clear(); s.push({ "title", true }); s.pop(); s.pop(); s.apply(); CHECK_EQ(s.size(), std::size_t{ 0 }); CHECK(s.drawOrder().empty()); CHECK_EQ(s.top(), std::string(""));
    s.replace({ "x", true }); s.apply(); CHECK_EQ(s.top(), std::string("x"));
}

